STRIDE = 128
FOOTER_START = 48 * STRIDE


@lru_cache(maxsize=64)
def status_footer(text):
    text = re.sub(r'~([^~]+)~', lambda m: {'degrees': '°', 'right_arrow': '→'}.get(m[1], '?'), text)
    lines = textwrap.wrap(' '.join(text.split()), width=42, max_lines=2, placeholder='...')
    frame = native.Frame()
    for index, line in enumerate(lines):
        frame.text(2, 52 if len(lines) == 1 else 48 + 8 * index, line)
    return frame.wire_bytes()[FOOTER_START:]


class KlipperStatus(native.KlipperStatus):
    """Keep the installed Inventure status layout, including its thermal icons."""
    def __init__(self, config):
        super().__init__(config)
        self._native_draw_text = self.draw_text
        self.draw_text = self._status_text
        self._source_wire = self._compact_wire = self._source_text = None

    def _status_text(self, row, col, mixed_text, eventtime):
        if row == 3 and col == 0:
            self._footer_text = str(mixed_text)[:240]
        return self._native_draw_text(row, col, mixed_text, eventtime)

    def render(self, now, board):
        self._footer_text = None
        wire = super().render(now, board)
        if self._footer_text is None:
            return wire
        if wire != self._source_wire or self._footer_text != self._source_text:
            self._compact_wire = wire[:FOOTER_START] + status_footer(self._footer_text)
            self._source_wire, self._source_text = wire, self._footer_text
        return self._compact_wire


@lru_cache(maxsize=16)
def _icon_rows(pixels):
    """Prepare original 50×50 grayscale values at the odd x origin (203)."""
    rows = []
    for start in range(0, 2500, 50):
        row = pixels[start:start + 50]
        middle = bytes((row[x] << 4) | row[x + 1] for x in range(1, 49, 2))
        rows.append(bytes([row[0]]) + middle + bytes([row[-1] << 4]))
    return tuple(rows)


@lru_cache(maxsize=24)
def _menu_text(atlas, labels, has_icon, notice):
    frame = native.Frame()
    for row, label in enumerate(labels):
        frame.oem_text(19, row * 12, label, atlas, right=193 if has_icon else 253)
    if notice:
        frame.oem_text(203, 14, 'INFO', atlas, right=255)
        frame.oem_text(203, 30, 'NO ACT', atlas, right=255)
    return frame.wire_bytes()


@lru_cache(maxsize=1)
def _sprite_catalog():
    return json.loads(Path(__file__).with_name('inventure_activity_sprites.json').read_text())


def _activity_catalog():
    return _sprite_catalog()['symbols']


@lru_cache(maxsize=1)
def project_symbols():
    symbols = {}
    for filename in ('inventure_project_activity_sprites.json', 'inventure_project_menu_sprites.json'):
        symbols.update(json.loads(Path(__file__).with_name(filename).read_bytes())['symbols'])
    return symbols


# These are the Inventure symbols used for each host workflow. r0323 supplies
# an animation for waiting/progress, and static glyphs for settings and faults.
ACTIVITY_SYMBOLS = {
    'heat_nozzle': 'progress', 'cooling': 'wait', 'clean_nozzle': 'progress',
    'filament_jam': 'error', 'filament_runout': 'warning', 'oled_brightness': 'settings',
    'link_status': 'information', 'sd_read': 'filecheck',
    'fan_upper': 'maintenance', 'fan_lower': 'maintenance',
}


def _unpack(frame, name):
    packed = zlib.decompress(base64.b64decode(frame['zlib_b64'], validate=True))
    if len(packed) != 1250 or sha256(packed).hexdigest() != frame['sha256']:
        raise ValueError('Invalid OLED activity frame: ' + name)
    return packed


@lru_cache(maxsize=1)
def sleep_wire():
    atlas = native.get_oem_assets()
    frame = native.Frame()
    frame.oem_text(4, 13, 'Sleep Mode', atlas, right=198)
    frame.oem_text(4, 33, 'Press the button to wake up.', atlas, right=198)
    wire = bytearray(frame.wire_bytes())
    packed = _unpack(_activity_catalog()['sleep']['frames'][0], 'sleep')
    for y in range(50):
        offset = (y + 7) * STRIDE + 101
        wire[offset:offset + 25] = packed[y * 25:(y + 1) * 25]
    return bytes(wire)


def _symbol(icon):
    if not icon:
        return None
    if icon.startswith('leveling:'):
        return _LEVELING_OEM['symbols'].get(icon[9:])
    if icon.startswith('project:'):
        return project_symbols().get(icon[8:])
    if icon.startswith('activity:'):
        name = icon[9:]
        return _activity_catalog().get(ACTIVITY_SYMBOLS.get(name, name))
    return None


@lru_cache(maxsize=32)
def _activity_rows(icon, index):
    packed = _unpack(_symbol(icon)['frames'][index], icon)
    # Repack each row at x=203, preserving its grayscale and blank edge nibbles.
    rows = []
    for start in range(0, len(packed), 25):
        row = int.from_bytes(packed[start:start + 25], 'big') << 4
        rows.append(row.to_bytes(26, 'big'))
    return tuple(rows)


def activity_index(view, now):
    if not view.get('animated'):
        return 0
    record = _symbol(view.get('icon') or '')
    if not record or len(record['frames']) <= 1 or not record['frame_ms']:
        return 0
    return int(now * 1000 / record['frame_ms']) % len(record['frames'])


@lru_cache(maxsize=24)
def _background(atlas, labels, icon, notice, index):
    wire = _menu_text(atlas, labels, bool(icon), notice)
    if not icon or notice:
        return wire
    # The OEM layout reserves this black strip exclusively for the sprite.
    # Unused outer nibbles and transparent pixels therefore remain black.
    result = bytearray(wire)
    rows = (_activity_rows(icon, index) if _symbol(icon)
            else _icon_rows(atlas.icons[icon]))
    for y, row in enumerate(rows, 13):
        start = y * STRIDE + 101
        result[start:start + len(row)] = row
    return bytes(result)


def _leveling_activity(run):
    """Describe real preparation actions using the shared M300 artwork.

    UI-only projection. No action is injected into the motion interpreter.
    Operator prompts and completed observations retain the Inventure OEM UI.
    """
    phase = run.get('phase')
    if phase not in ('preparing','heating','reference','measuring','finishing'):
        return None
    ui = run.get('ui') or {}
    action = ui.get('action') or {}
    modules = ui.get('modules') or ()
    kind = action.get('kind')
    if 'clean' in modules or action.get('stage') in ('clean','wipe'):
        return 'cleaning', 'Cleaning the nozzle.\nPlease wait.', 'project:clean_nozzle'
    if kind in ('heat','level_heat'):
        target = ui.get('target_c')
        line = 'Target: %.0f C\n' % target if type(target) in (float,int) else ''
        return 'heating', 'Heating the nozzles.\n'+line+'Please wait.', 'project:heat_nozzle'
    if 'select_tool' in modules:
        return 'selecting_t0', 'Selecting nozzle T0.\nPlease wait.', 'project:heat_nozzle'
    if kind in ('home','home_release'):
        axis = action.get('axis')
        icon = 'homing-z' if axis == 'Z' else 'homing-xy'
        return 'home_'+str(axis), 'Homing %s.\nPlease wait.' % axis, 'project:'+icon
    if phase == 'preparing':
        return 'preparing', 'Preparing the platform.\nPlease wait.', 'project:homing-all'
    if phase == 'heating':
        return 'heating', 'Heating / selecting T0.\nPlease wait.', 'project:heat_nozzle'
    if phase == 'finishing':
        return 'finishing', 'Parking the platform.\nVerifying the result.\nPlease wait.', 'project:homing-z'
    return None


def leveling_screen(run, screw_index=0):
    """Freeze only presentation fields from the existing r0323 procedure.

    Measurements stay in OEM steps (802/mm). Instructions, directions and
    turns come from the Inventure owner, never from the M300 screw formula.
    """
    keys = ('phase', 'awaiting_operator', 'next_point', 'candidate_depth_um',
            'center_error_steps', 'deformed', 'door_pause', 'error')
    screen = {key: run.get(key) for key in keys}
    screen['heights'] = tuple((run.get('heights_steps') or {}).get(i,
                             (run.get('heights_steps') or {}).get(str(i))) for i in range(5))
    screen['instructions'] = tuple(dict(item) for item in run.get('instructions', ()))
    screen['screw_index'] = min(max(0, screw_index), max(0, len(screen['instructions']) - 1))
    phase = screen['phase']
    key = None
    if phase == 'await_knobs' and screen['awaiting_operator']:
        key = 'knobs'
    elif phase == 'adjust' and screen['awaiting_operator'] and screen['instructions']:
        instruction = screen['instructions'][screen['screw_index']]
        key = instruction['knob']+'_'+instruction['action']
    elif phase == 'measuring':
        key = 'front' if screen['next_point'] in (0,1) else 'back' if screen['next_point'] in (3,4) else 'center'
    elif phase == 'reference':
        key = 'center'
    elif phase == 'candidate' and screen['deformed']:
        key = 'deformed'
    elif phase in ('candidate','saved'):
        key = 'done'
    elif phase == 'failed':
        key = 'failed'
    record = _LEVELING_OEM['messages'].get(key)
    screen['body'] = record['text'] if record else {
        'preparing':'Preparing platform.\nAutomatic T0 selection.\nPlease wait.',
        'await_knobs':'Preparing safe access.\nPlease wait.',
        'adjust':'Preparing safe access.\nPlease wait.',
        'heating':'Heating the nozzles.\nPlease wait.',
        'finishing':'Finishing calibration.\nPlease wait.',
        'cancelled':'Platform leveling cancelled.\nNo new result saved.',
    }.get(phase,'Platform leveling')
    if key and key.endswith(('_tighten','_loosen')):
        screen['body'] %= (abs(instruction.get('delta_steps',0))/802.,instruction['turns'],
                           'turn' if instruction['turns']==1 else 'turns')
    screen['icon'] = 'leveling:'+record['sprite'] if record and record['sprite'] else 'activity:wait'
    activity = _leveling_activity(run)
    if activity:
        screen['activity'], screen['body'], screen['icon'] = activity
    elif phase in ('await_knobs','adjust') and not screen['awaiting_operator']:
        screen['activity'] = 'preparing_access'
        screen['icon'] = 'project:homing-z'
    elif phase == 'cancelled':
        screen['icon'] = 'leveling:'+_LEVELING_OEM['messages']['failed']['sprite']
    if phase in ('candidate','saved') and not screen['deformed']:
        screen['icon'] = None
    screen['animated'] = len((_symbol(screen['icon']) or {}).get('frames',())) > 1
    return screen


def leveling_wire(screen, labels, selected, index=0):
    # Bounded cache: stable procedure phases do not redraw in the reactor.
    return _leveling_wire(json.dumps(screen, sort_keys=True),
                          str(labels[selected]) if labels else '', index)


def _line(frame, x0, y0, x1, y1, level=15):
    count = max(abs(x1-x0), abs(y1-y0), 1)
    for step in range(count+1):
        frame.pixel(round(x0+(x1-x0)*step/count), round(y0+(y1-y0)*step/count), level)


def _box(frame, x, y, width, height, level=15):
    for x0, y0, x1, y1 in ((x,y,x+width,y), (x,y,x,y+height),
                           (x+width,y,x+width,y+height), (x,y+height,x+width,y+height)):
        _line(frame, x0,y0,x1,y1,level)


def _pad_map(frame, screen):
    # Signed point values in the same rear/front order as the Fluidd diagram.
    _box(frame, 173, 10, 80, 38, 5)
    for point,x,y in ((4,174,10),(3,216,10),(2,195,26),(1,174,42),(0,216,42)):
        value = screen['heights'][point]
        text = '%+.2f' % (value/802.) if type(value) is int else ' --- '
        frame.text(x,y,text,15 if point == screen.get('next_point') else 9)
        if point == screen.get('next_point'):
            _box(frame,x-1,y-1,32,9)


@lru_cache(maxsize=32)
def _leveling_wire(serialized, choice, index):
    screen = json.loads(serialized)
    frame = native.Frame()
    phase = screen['phase']
    if phase in ('candidate','saved') and not screen['deformed']:
        frame.text(2,0,'Leveling saved' if phase=='saved' else 'Calibration done')
        depth, error = screen.get('candidate_depth_um'), screen.get('center_error_steps')
        if type(depth) is int:frame.text(2,16,'Depth %.3f mm' % (depth/1000.))
        if type(error) is int:frame.text(2,28,'Center %+.3f mm' % (error/802.))
        frame.text(2,42,'Result saved' if phase=='saved' else 'Review before saving')
        _pad_map(frame,screen)
    else:
        atlas = native.get_oem_assets()
        lines = screen['body'].split('\n')
        y = max(0,(50-len(lines)*12)//2)
        for line in lines:
            width = sum(atlas.glyphs.get(ord(c),atlas.glyphs[ord('?')])[0]+1 for c in line)-1
            frame.oem_text(max(0,(192-width)//2),y,line,atlas,right=192)
            y += 12
        if phase == 'adjust' and screen['awaiting_operator']:
            frame.text(4,46,'HOT / gloves; %d of %d' % (screen['screw_index']+1,len(screen['instructions'])))
        record = _symbol(screen['icon'])
        if record:
            raw = _unpack(record['frames'][index % len(record['frames'])],screen['icon'])
            for row in range(50):
                for col in range(50):
                    byte = raw[row*25+col//2]
                    frame.pixel(203+col,13+row,byte & 15 if col & 1 else byte >> 4)
    # Preserve the complete original 50x50 sprite in the right-hand area.
    _line(frame,0,54,191,54,5)
    frame.text(2,57,'> '+choice[:29])
    return frame.wire_bytes()


def menu_wire(view, atlas=None, index=0):
    if view.get('leveling') is not None:
        return leveling_wire(view['leveling'], view['labels'], view['selected'], index)
    if (view.get('page') == 'maintenance' and view.get('labels')
            and view['labels'][view['selected']] == 'Platform leveling'):
        view = dict(view, icon='leveling:0x0802A218')
    atlas = atlas or native.get_oem_assets()
    labels = view['labels']
    if not labels:
        return bytes(8192)
    icon = view.get('icon')
    if icon and not _symbol(icon):
        pixels = atlas.icons.get(icon)
        if not isinstance(pixels, bytes) or len(pixels) != 2500:
            return native.Frame().oem_menu(view, atlas).wire_bytes()
    pinned = labels[0] in ('Back', 'Powrót')
    selected = min(max(0, view['selected']), len(labels) - 1)
    indices = list(range(min(5, len(labels))))
    if len(labels) > 5:
        first = min(max(int(pinned), int(view.get('window', int(pinned)))), len(labels) - 5 + int(pinned))
        indices = ([0] if pinned else []) + list(range(first, first + 5 - int(pinned)))
    background = _background(atlas, tuple(labels[i] for i in indices), icon, bool(view.get('notice')), index)
    if selected not in indices:
        return background
    result = bytearray(background)
    center = indices.index(selected) * 12 + 5
    back = pinned and selected == 0
    for dy in range(-4, 5):
        x = 8 + abs(dy) if back else 12 - abs(dy)
        result[(center + dy) * STRIDE + x // 2] |= 15 if x & 1 else 240
    return bytes(result)
